//! `match_axes`, which finds for each axis of one Frame the corresponding
//! axis of another, checked against the C library.
//!
//! `match_axes_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/match_axes_probe.c`, which calls
//! `astMatchAxes( frm1, frm2, axes )` for every pair from the list of Frames
//! [`frame`] builds. C dispatches to the `MatchAxesX` of `frm2`, which
//! SkyFrame, CmpFrame, FrameSet and Region override, so the list holds each
//! of those classes, permuted and nested CmpFrames among them.
//! The Frames are held as `Box<dyn Frame>`, so the test calls
//! `frm2.match_axes_x(frm1)`, which is what `frm1.match_axes(frm2)` calls.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "match_axes_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{
    BasicFrameBuilder, CmpFrame, Frame, FrameRef, FrameSet, SkyFrame, SpecFrame, TimeFrame,
};
use starlink_ast::mappings::UnitMap;
use starlink_ast::regions::CircleBuilder;

fn basic(naxes: usize) -> Box<dyn Frame> {
    Box::new(BasicFrameBuilder::new(naxes).build().unwrap())
}

fn sky() -> Box<dyn Frame> {
    Box::new(SkyFrame::unset_system())
}

fn spec() -> Box<dyn Frame> {
    Box::new(SpecFrame::unset_system())
}

fn spec_sky() -> CmpFrame {
    CmpFrame::new(spec(), sky())
}

/// Frame `i` of the list `match_axes_probe.c` builds in `make`.
fn frame(i: usize) -> Box<dyn Frame> {
    match i {
        0 => sky(),
        1 => {
            let mut f = SkyFrame::unset_system();
            f.perm_axes(&[2, 1]).unwrap();
            Box::new(f)
        }
        2 => spec(),
        3 => basic(1),
        4 => Box::new(CmpFrame::new(sky(), spec())),
        5 => {
            let mut f = CmpFrame::new(sky(), spec());
            f.perm_axes(&[3, 2, 1]).unwrap();
            Box::new(f)
        }
        6 => Box::new(spec_sky()),
        7 => {
            let mut f = CmpFrame::new(basic(1), sky());
            f.perm_axes(&[2, 3, 1]).unwrap();
            Box::new(f)
        }
        8 => {
            let mut fs = FrameSet::new(basic(2));
            fs.add_frame(FrameRef::Base, Box::new(UnitMap::new(2)), sky())
                .unwrap();
            Box::new(fs)
        }
        9 => {
            let mut fs = FrameSet::new(basic(3));
            fs.add_frame(
                FrameRef::Base,
                Box::new(UnitMap::new(3)),
                Box::new(spec_sky()),
            )
            .unwrap();
            Box::new(fs)
        }
        10 => Box::new(
            CircleBuilder::new(SkyFrame::unset_system(), vec![0.0, 0.0])
                .unwrap()
                .radius(0.1)
                .build()
                .unwrap(),
        ),
        11 => Box::new(CmpFrame::new(Box::new(spec_sky()), basic(1))),
        12 => Box::new(TimeFrame::unset_system()),
        _ => unreachable!(),
    }
}

#[test]
fn match_axes_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(i, j, expected) in cases::CASES {
        let (frm1, frm2) = (frame(i), frame(j));
        let got = frm2.match_axes_x(frm1.as_ref()).unwrap();
        if got != expected {
            failures.push(format!(
                "frm1 {i} frm2 {j}: got {got:?}, C gives {expected:?}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
